<script>
(()=>{const $=id=>document.getElementById(id);function rgb(hex){hex=hex.trim();if(/^#[0-9a-f]{3}$/i.test(hex))hex='#'+[hex[1],hex[2],hex[3]].map(x=>x+x).join('');if(!/^#[0-9a-f]{6}$/i.test(hex))return null;return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255)}function lum(c){return c.map(v=>v<=0.04045?v/12.92:Math.pow((v+0.055)/1.055,2.4)).reduce((s,v,i)=>s+v*[0.2126,0.7152,0.0722][i],0)}function go(){const f=rgb($('fg').value),b=rgb($('bg').value);if(!f||!b){$('ratio').textContent=$('aa').textContent=$('aal').textContent=$('aaa').textContent=$('aaal').textContent='—';$('note').textContent='Use 3- or 6-digit hex colors such as #fff or #1f2937.';$('note').className='helper danger';return}const l1=lum(f),l2=lum(b),r=(Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05);$('ratio').textContent=r.toFixed(2)+':1';$('aa').textContent=r>=4.5?'Pass':'Fail';$('aal').textContent=r>=3?'Pass':'Fail';$('aaa').textContent=r>=7?'Pass':'Fail';$('aaal').textContent=r>=4.5?'Pass':'Fail';$('preview').style.color=$('fg').value;$('preview').style.backgroundColor=$('bg').value;$('note').textContent='Threshold checks use the unrounded ratio. Large text has a specific WCAG size/weight definition; UI components and non-text graphics use other criteria.';$('note').className='helper'}['fg','bg'].forEach(id=>$(id).addEventListener('input',go));go()})();
</script>
